// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenefitCase) predicate.BenefitCase {
	return predicate.BenefitCase(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenefitCase) predicate.BenefitCase {
	return predicate.BenefitCase(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenefitCase) predicate.BenefitCase {
	return predicate.BenefitCase(sql.NotPredicates(p))
}
